%% Size check
expectedSize = [length(coefs.alphas), length(coefs.betas)];
coefNames = ["CLs", "CDs", "CYs", "Croll", "Cpitch", "Cyaw"];
for i = 1:length(coefNames)
    actualSize = size(coefs.(coefNames(i)));
    if ~isequal(actualSize, expectedSize)
        error("%s must be size %d x %d. Current size is %d x %d.", ...
            coefNames(i), expectedSize(1), expectedSize(2), actualSize(1), actualSize(2));
    end
